31	const QS = new URLSearchParams(location.search);
32	const on = (k: string) => QS.get(k) === '1';
33	export const M04 = {
34	  ring: on('m04ring'),
35	  foam: on('m04foam'),
36	  bub: on('m04bub'),
37	  arrow: on('m04arrow'),
38	  wave: on('m04wave'),
39	  river: on('m04river'),
40	  gold: on('m04gold'),
41	  mouth: on('m04mouth'),
42	  room: on('m04room'),
43	  foam3: on('m04foam3'),
44	  pink: on('m04pink'),
45	  arr5: on('m04arr5'),
46	  arr3d: on('m04arr3d'),
47	  lay: on('m04lay'),
48	  num: (k: string, d: number) => (QS.has(k) ? Number(QS.get(k)) : d),
49	};
50	
51	export interface M04Ctx {
52	  group: THREE.Group;
53	  shared: Record<string, THREE.IUniform>;
54	  proj: THREE.PerspectiveCamera;
55	  /** tube axis in group-local coordinates (x lateral, y up from the slide, z = -down the slide) */
56	  cx: number; cy: number; z0: number; len: number; r: number; outerR: number;
57	  hideOld: (names: string[]) => void;
58	}
