60	const VERT = /* glsl */ `
61	uniform mat4 uProjVP;
62	attribute vec2 aK;
63	#ifdef RFEW
64	attribute vec2 aF;          // r18 m04rfew: x = ring coordinate along the tunnel in painted-period units, y = ring scale
65	varying vec2 vF;
66	#endif
67	varying vec4 vProj;
68	varying vec3 vW;
69	varying vec3 vN;
70	varying vec2 vK;
71	void main() {
72	  vec4 wp = modelMatrix * vec4(position, 1.0);
73	  vProj = uProjVP * wp;
74	  vW = wp.xyz;
75	  vK = aK;
76	#ifdef RFEW
77	  vF = aF;
78	#endif
79	  vN = normalize(mat3(modelMatrix) * normal);
80	  gl_Position = projectionMatrix * viewMatrix * wp;
81	}`;
