102	uniform sampler2D uRingTile; // tile_ring.png: the painted ring colour at every angle (rows 56..176 = band near edge .. lip)
103	uniform float uPaint;      // how much of the painted ring colour drives the bands (m04paint)
104	uniform float uBulge;      // r13 m04bulge: each band shaded as a ROUNDED tube (bright middle, darker edges) like the painted rings
105	uniform float uCopper;     // r13 m04copper: rich polished COPPER-gold ramp (dark maroon grooves -> copper -> warm-gold highlights)
106	uniform float uGoldY;      // m04gold: polished YELLOW-gold ramp (bright yellow-white highlights), fewer magenta tints
107	uniform float uMouthT;     // m04mouth: the painted mouth ring texture on the opening (tile_mouth.png)
108	uniform sampler2D uMouthTex;
109	uniform vec3 uMouthRho;    // tile rows: rho at the top row, rho at the bottom row (fitted mouth plane z0); z: rho offset
110	                           // (the painted band lies 0.1 u inside the fitted outer radius: lips onto the modeled lips)
111	uniform vec3 uProjPos;
112	uniform float uRPaint;     // r15 m04rpaint: mix of the user's PAINTED inner ring (tile_ring_paint.png) on every inner ring band
113	uniform sampler2D uRTex;   // cols psi -pi..pi (0 = top, + = right), rows s 0 (painted groove) .. 1 (next groove), deeper
114	uniform vec4 uRLip;        // x: painted lip-line s, y: modeled u that carries the painted lip line, z: modeled shading amount,
115	                           // w: modeled u where the painted groove begins (held dark to the period end)
116	uniform float uRJit;       // per-ring angle offset (rad, +-): the painted highlights do not line up ring after ring
117	uniform vec2 uRWarm;       // r16 m04rwarm: x = amount, y = where the grade starts (fraction of the camera -> end-glow distance)
118	uniform vec4 uRDots;       // r16 m04rpdots: x = amount, y = dot cells per ring, z = fraction of cells lit, w = core radius (u)
119	uniform float uRVar;       // r17 m04rpvar: number of painted rings stacked in the atlas (0 = the single painted ring 1)
120	uniform vec4 uRPol;        // r18 m04rpol: x amount, y luma pivot, z contrast gain above it, w below it
121	uniform vec2 uRPol2;       // r18 m04rpol: x sharp sheen (reflection of the bright end), y grazing-angle brightening
122	uniform vec4 uRCr;         // r18 m04rpcr: x amount, y bright lip line half width, z dark lip-edge line half width, w band-start corner (u)
123	uniform vec4 uRNear;       // r19b m04rnear: x amount, y target sub-band length (world u), z/w sub-band size on screen (px of a
124	                           // 1536 px tall portrait view, from world length, distance and foreshortening) where the detail starts / is full
