59	uniform vec2 uNearFar;
60	uniform sampler2D uPatch;
61	uniform float uPatchK;
62	uniform vec3 uProjPos;
63	uniform vec4 uPjPost;
64	uniform vec2 uPjRes;
65	uniform float uMode;          // 0 room wall / mouth ring: artwork patch; 1 tunnel wall: painted ring tile; 2 water: painted river tile
66	uniform sampler2D uTile;
67	uniform vec4 uTileA;          // mode 1: cx, cy, mouth z, ring period | mode 2: lateral half-width, along start, along length, -
68	uniform float uLipS;
69	uniform sampler2D uFill;      // plate04_fillmask: where the plate is a provisional fill (HUD, title, Benny, coins)
70	uniform float uMoved;         // 0 in the approved view, 1 once the camera has moved away from it
