76	                              //   curve in approved-image fractions  yTop = y + w * (x - z)^2
77	varying vec4 vProj;
78	varying vec3 vW;
79	varying vec3 vN;
80	varying vec3 vL;
81	${PROJ05_INVERSE}
82	// triplanar, mirrored-repeat sampling (slide-local coordinates) of the patch cut from the approved artwork
83	vec3 patchColor() {
