88	float linZ(float d) { float n = uNearFar.x, f = uNearFar.y; float z = d * 2.0 - 1.0; return 2.0 * n * f / (f + n - z * (f - n)); }
89	// milestone 2: world-anchored design tiles cut from the approved artwork for the views the picture never resolved
90	vec3 tileColor(vec3 pc) {
