110	  if (uMode > 1.5) {
111	    float along = -vL.z;                                    // down the slide from Benny's water point
112	    vec2 uv = vec2(vL.x / (2.0 * uTileA.x) + 0.5, (along - uTileA.y) / uTileA.z);
113	    float inRiver = 1.0 - smoothstep(0.9 * uTileA.x, uTileA.x, abs(vL.x));
